#!/usr/bin/env node
// Throwaway reconnaissance: how many map candidates live in different
// datestamp windows of the e-rara `zuz` (ZB Zürich) OAI set?
import { writeFile } from 'node:fs/promises';

const UA = 'Kartenzeit/1.0 (Canton-Zurich design study; contact: project maintainers)';
const decode = (s) =>
  String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#039;/g, "'").trim();
const all = (xml, tag) => [...xml.matchAll(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'g'))].map((m) => decode(m[1]));
const first = (xml, tag) => all(xml, tag)[0] ?? null;

async function get(url) {
  const res = await fetch(url, { headers: { 'user-agent': UA } });
  if (!res.ok) throw new Error(`${res.status} ${url}`);
  return res.text();
}

async function pages(set, maxPages, from, until) {
  const out = [];
  let token = null;
  for (let i = 0; i < maxPages; i++) {
    const url = token
      ? `https://www.e-rara.ch/oai?verb=ListRecords&resumptionToken=${encodeURIComponent(token)}`
      : `https://www.e-rara.ch/oai?verb=ListRecords&metadataPrefix=oai_dc&set=${set}` +
        (from ? `&from=${from}` : '') + (until ? `&until=${until}` : '');
    let xml;
    try { xml = await get(url); } catch (e) { out.push({ error: String(e) }); break; }
    for (const rec of all(xml, 'record')) {
      const types = all(rec, 'dc:type');
      out.push({
        isMap: types.includes('Map'),
        year: Number(first(rec, 'dc:date')) || null,
        title: (all(rec, 'dc:title')[0] || '').slice(0, 70),
        sets: all(rec, 'setSpec').join(','),
        oai: first(rec, 'identifier'),
      });
    }
    const m = xml.match(/<resumptionToken[^>]*>([^<]+)<\/resumptionToken>/);
    token = m ? m[1] : null;
    if (!token) break;
    await new Promise((r) => setTimeout(r, 100));
  }
  return out;
}

const windows = JSON.parse(process.argv[2] || '[]');
const report = [];
for (const [label, set, maxPages, from, until] of windows) {
  const recs = await pages(set, maxPages, from, until);
  const errs = recs.filter((r) => r.error);
  const maps = recs.filter((r) => r.isMap && r.year);
  console.log(`\n== ${label}: ${recs.length} records, ${maps.length} map candidates ${errs.length ? JSON.stringify(errs.slice(0, 2)) : ''}`);
  for (const m of maps.sort((a, b) => a.year - b.year)) console.log(`   ${m.year}  ${m.title}   [${m.sets}]`);
  report.push({ label, set, maxPages, from, until, total: recs.length, maps: maps.map((m) => ({ y: m.year, t: m.title, sets: m.sets })) });
}
await writeFile('/tmp/oai-probe.json', JSON.stringify(report, null, 1));

