 * returns up to 100 records per page with `<vl:id>` (the IIIF title id),
 * `<vl:prefix>` (holding corpus, e.g. `zuz`) and the MODS `<coordinates>`
 * statement. Those ids are then confirmed through the same paths as the OAI
 * records (OAI `GetRecord` + IIIF manifest), so nothing is trusted twice.
 */
const SRU_ENDPOINT = 'https://www.e-rara.ch/sru';

async function sruSearch(cql, maxRecords = 100) {
  const records = [];
  for (let start = 1; start <= maxRecords; start += 100) {
    const url =
      `${SRU_ENDPOINT}?operation=searchRetrieve&version=1.2&query=${encodeURIComponent(cql)}` +
      `&startRecord=${start}&maximumRecords=100&recordSchema=mods`;
    const xml = await get(url);
    const chunks = [...xml.matchAll(/<srw:record>([\s\S]*?)<\/srw:record>/g)].map((m) => m[1]);
    if (!chunks.length) break;
    for (const chunk of chunks) records.push(parseSruRecord(chunk));
    if (chunks.length < 100) break;
    await sleep(120);
  }
  return records.filter(Boolean);
}

