#!/usr/bin/env node
/**
 * Verify that every published record still points at a live upstream.
 *
 * The seed in `public/data/records.json` promises a thumbnail, a link to the
 * original collection record and (for digitised works) an IIIF manifest and the
 * library's own viewer. Those URLs live at other institutions, so they can rot
 * without anything in this repository changing. This script probes them from the
 * committed data and fails when one stops answering.
 *
 * It is deliberately *not* part of `npm run build`: the build must work offline
 * and without network access. Run it before shipping a data change:
 *
 *   npm run verify:sources
 *   npm run verify:sources -- --json /tmp/verify.json --concurrency 8
 *
 * Politeness: one descriptive User-Agent, bounded concurrency (default 6), a
 * 25 s timeout per request, two attempts per URL and a HEAD-free GET so that
 * content-type/长度 are really checked. Nothing is written to the repository.
 */
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const args = process.argv.slice(2);
const argValue = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const CONCURRENCY = Number(argValue('concurrency', '6'));
const TIMEOUT = Number(argValue('timeout', '25000'));
const JSON_OUT = argValue('json', null);
const ROOT = resolve(new URL('..', import.meta.url).pathname);
const UA = 'Kartenzeit/1.0 (Canton-Zurich design study; source verification; contact: project maintainers)';

/** What each record kind is expected to answer with. */
const KIND_RULES = {
  thumbnail: { kinds: ['image/'], label: 'Vorschaubild' },
  iiifManifest: { kinds: ['application/json', 'application/ld+json', 'text/json'], label: 'IIIF-Manifest' },
  record: { kinds: ['text/html'], label: 'Originaldatensatz' },
  viewer: { kinds: ['text/html'], label: 'Bibliotheks-Viewer' },
  provider: { kinds: ['text/html'], label: 'Anbieter-Seite' },
};

function collectTargets(recordsDoc, sourcesDoc) {
  const targets = [];
  for (const record of recordsDoc.records ?? recordsDoc) {
    const push = (kind, url) => {
      if (typeof url === 'string' && /^https?:\/\//.test(url)) targets.push({ kind, id: record.id, url });
    };
    push('thumbnail', record.thumbnail);
    push('iiifManifest', record.iiifManifest);
    push('record', record.recordUrl);
    push('viewer', record.viewerUrl);
  }
  for (const provider of sourcesDoc.providers ?? []) {
    for (const key of ['homepage', 'terms']) {
      const url = provider[key];
      if (typeof url === 'string' && /^https?:\/\//.test(url)) {
        targets.push({ kind: 'provider', id: provider.id, url });
      }
    }
  }
  return targets;
}

async function probe(target) {
  const expected = KIND_RULES[target.kind]?.kinds ?? [];
  let last = { status: 0, detail: 'no attempt' };
  for (let attempt = 1; attempt <= 2; attempt += 1) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), TIMEOUT);
    try {
      const res = await fetch(target.url, {
        headers: { 'user-agent': UA, accept: '*/*' },
        redirect: 'follow',
        signal: ctrl.signal,
      });
      const body = await res.arrayBuffer();
      const type = (res.headers.get('content-type') || '').split(';')[0].trim();
      const okType = expected.length === 0 || expected.some((e) => type.startsWith(e));
      const ok = res.status === 200 && body.byteLength > 0 && okType;
      last = {
        status: res.status,
        bytes: body.byteLength,
        type,
        ok,
        detail: ok ? `${res.status} ${type} ${(body.byteLength / 1024).toFixed(1)} KiB` : `${res.status} ${type || 'no content-type'} ${body.byteLength} B`,
      };
      if (ok) return { ...target, ...last, attempt };
    } catch (error) {
      last = { status: 0, bytes: 0, type: '', ok: false, detail: `network: ${String(error).slice(0, 80)}` };
    } finally {
      clearTimeout(timer);
    }
    if (attempt === 1) await new Promise((r) => setTimeout(r, 800));
  }
  return { ...target, ...last, attempt: 2 };
}

async function pool(items, limit, fn) {
  const out = [];
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, async () => {
      while (next < items.length) {
        const i = next++;
        out[i] = await fn(items[i]);
      }
    }),
  );
  return out;
}

const recordsDoc = JSON.parse(await readFile(resolve(ROOT, 'public/data/records.json'), 'utf8'));
const sourcesDoc = JSON.parse(await readFile(resolve(ROOT, 'public/data/sources.json'), 'utf8'));
const targets = collectTargets(recordsDoc, sourcesDoc);
console.log(`Prüfe ${targets.length} URLs aus ${(recordsDoc.records ?? []).length} Datensätzen …`);

const results = await pool(targets, CONCURRENCY, probe);
const failed = results.filter((r) => !r.ok);

const byKind = {};
for (const r of results) {
  byKind[r.kind] = byKind[r.kind] || { ok: 0, failed: 0 };
  byKind[r.kind][r.ok ? 'ok' : 'failed'] += 1;
}
for (const [kind, counts] of Object.entries(byKind)) {
  const rule = KIND_RULES[kind]?.label ?? kind;
  console.log(`  ${rule.padEnd(18)} ${counts.ok}/${counts.ok + counts.failed} erreichbar`);
}
for (const r of failed) {
  console.log(`  ✖ ${r.kind} ${r.id} ${r.url} — ${r.detail}`);
}
console.log(failed.length ? `✖ ${failed.length} von ${results.length} URLs antworten nicht` : `✓ alle ${results.length} URLs erreichbar`);

if (JSON_OUT) {
  await writeFile(
    resolve(JSON_OUT),
    JSON.stringify({ checkedAt: new Date().toISOString(), total: results.length, failed: failed.length, results }, null, 1),
  );
  console.log(`report: ${JSON_OUT}`);
}
process.exit(failed.length ? 1 : 0);

